import json,copy
from pathlib import Path
base=Path('content/isc2-cc-2026/learning/published');l=json.loads((base/'lessons/lesson-d1-11-control-functions.json').read_text(encoding='utf-8'))
pair=lambda en,th:{'en':en,'th':th}
rows=lambda *items:[[pair(*c) for c in r] for r in items]
slides=[]
def add(id,en,th,lead,rs,detail,foot):
 s=copy.deepcopy(l['slides'][0]);s.update(id=id,title=pair(en,th),referenceIds=['ref-outline','ref-a','ref-b','ref-ethics']);s['blocks']=[{'kind':'text','text':pair(*lead)},{'kind':'table','caption':pair('Original professional-practice examples','ตัวอย่างการปฏิบัติงานวิชาชีพที่แต่งขึ้น'),'columns':[pair('Focus','จุดเน้น'),pair('Action or decision','การกระทำหรือการตัดสินใจ'),pair('Evidence or boundary','หลักฐานหรือขอบเขต')],'rows':rs},{'kind':'text','text':pair(*detail)},{'kind':'text','text':pair(*foot)}];slides.append(s)
add('slide-01-access-and-authority','Technical access is not permission for every purpose.','เข้าถึงทางเทคนิคได้ ไม่ได้แปลว่าทำได้ทุกวัตถุประสงค์',('Professional conduct starts with the purpose and authority for your action.','เริ่มจากวัตถุประสงค์และอำนาจที่รองรับการกระทำ'),rows(
 [('Capability','ความสามารถ'),('An administrator can open payroll records.','ผู้ดูแลระบบเปิดข้อมูลเงินเดือนได้'),('A powerful account describes ability.','บัญชีสิทธิ์สูงบอกว่าทำอะไรได้')],
 [('Authorized purpose','วัตถุประสงค์ที่อนุญาต'),('A support task needs approved scope and a real need.','งานสนับสนุนต้องมีขอบเขตที่อนุมัติและความจำเป็น'),('Curiosity is not a business justification.','ความอยากรู้ไม่ใช่เหตุผลทางงาน')]),
 ('A §46 distinguishes technical access from ethical or business authorization. B §8 adds respect for rights and public welfare. In this original example, an administrator troubleshooting payroll should confirm the assigned task, permitted records and handling restrictions before access. An account that can read every record does not justify reading colleagues’ salaries out of curiosity. Use only the access and information needed, protect what is encountered, and ask the appropriate owner when purpose or scope is unclear. An apparently helpful intention does not create permission. Professional conduct combines honesty, confidentiality, responsibility and respect with applicable requirements. L02 explains system authorization; this lesson adds the professional decision about whether and how to use an available capability.','A §46 แยกการเข้าถึงทางเทคนิคออกจากอำนาจทางจริยธรรมหรือธุรกิจ B §8 เสริมการเคารพสิทธิ์และประโยชน์ส่วนรวม ตัวอย่างแต่งขึ้นนี้ผู้ดูแลที่แก้ระบบเงินเดือนควรยืนยันงานที่ได้รับ ข้อมูลที่อนุญาต และข้อจำกัดการจัดการก่อนเข้าใช้ บัญชีที่อ่านได้ทุกระเบียนไม่ได้เป็นเหตุให้อ่านเงินเดือนเพื่อนเพราะอยากรู้ ใช้สิทธิ์และข้อมูลเท่าที่งานจำเป็น ปกป้องสิ่งที่พบ และถามผู้รับผิดชอบเมื่อขอบเขตไม่ชัด เจตนาว่าจะช่วยไม่ได้สร้างสิทธิ์ขึ้นเอง ความประพฤติวิชาชีพรวมความซื่อสัตย์ การรักษาความลับ ความรับผิดชอบ การเคารพผู้อื่น และข้อกำหนดที่เกี่ยวข้อง L02 อธิบายการอนุญาตของระบบ ส่วนบทนี้พิจารณาว่าควรใช้ความสามารถนั้นหรือไม่และอย่างไร'),('Confirm purpose and scope before using privileged access.','ยืนยันวัตถุประสงค์และขอบเขตก่อนใช้สิทธิ์สูง'))
add('slide-02-professional-conduct','Professional conduct makes trust observable.','ความประพฤติวิชาชีพต้องเห็นได้จากการทำงาน',('A code sets expectations; everyday decisions must carry them out.','หลักจรรยาบรรณวางความคาดหวัง การตัดสินใจจริงต้องทำให้เกิดผล'),rows(
 [('Honesty and respect','ซื่อสัตย์และเคารพ'),('Describe findings and uncertainty fairly.','รายงานข้อค้นพบและความไม่แน่นอนอย่างเป็นธรรม'),('Do not invent results or blame without evidence.','ไม่แต่งผลหรือกล่าวโทษโดยไร้หลักฐาน')],
 [('Confidentiality','รักษาความลับ'),('Share necessary information with authorized recipients.','ส่งเฉพาะข้อมูลที่จำเป็นให้ผู้รับที่มีสิทธิ์'),('A valid report still needs safe handling.','รายงานที่ถูกต้องก็ต้องจัดการอย่างปลอดภัย')],
 [('Responsibility','รับผิดชอบ'),('Own mistakes, disclose conflicts and follow through.','รับผิดชอบความผิดพลาด เปิดเผยผลประโยชน์ขัดกัน และติดตามงาน'),('A signed policy alone does not prove conduct.','ลงนามรับนโยบายอย่างเดียวไม่พิสูจน์พฤติกรรม')]),
 ('A §46 lists integrity, confidentiality, professionalism, responsibility, respect and compliance with applicable laws or regulations. B §8 emphasizes ethical behavior under competing interests. A professional code makes these expectations explicit, but a signed acknowledgment is not evidence that every action meets them. For example, an analyst who sent a report to the wrong authorized team should promptly follow the approved correction and reporting process rather than quietly hide the mistake. Separate verified facts from assumptions, communicate respectfully, and disclose a personal interest that could distort a recommendation so it can be managed. Confidentiality and honest reporting must be considered together: protect sensitive details while ensuring the responsible people receive accurate information. A manager’s request does not excuse falsification or unauthorized access.','A §46 ระบุความซื่อตรง การรักษาความลับ ความเป็นมืออาชีพ ความรับผิดชอบ ความเคารพ และการทำตามกฎหมายหรือข้อบังคับที่เกี่ยวข้อง B §8 เน้นพฤติกรรมเมื่อผลประโยชน์ขัดกัน หลักจรรยาบรรณทำความคาดหวังเหล่านี้ให้ชัด แต่การลงชื่อรับทราบไม่ได้พิสูจน์ว่าทุกการกระทำถูกต้อง เช่น นักวิเคราะห์ส่งรายงานให้ทีมที่มีสิทธิ์แต่ผิดทีม ควรแก้ไขและรายงานตามกระบวนการที่อนุมัติทันที ไม่ปกปิดเงียบ ๆ แยกข้อเท็จจริงที่ตรวจแล้วออกจากสมมติฐาน สื่อสารอย่างเคารพ และเปิดเผยผลประโยชน์ส่วนตัวที่อาจบิดคำแนะนำเพื่อจัดการอย่างเหมาะสม ต้องคิดเรื่องความลับพร้อมความซื่อสัตย์ ป้องกันรายละเอียดอ่อนไหวและให้ผู้รับผิดชอบได้ข้อมูลถูกต้อง คำสั่งหัวหน้าไม่ใช่ข้อยกเว้นให้ปลอมผลหรือเข้าใช้โดยไม่มีอำนาจ'),('Trust depends on accurate words and responsible actions.','ความไว้วางใจต้องมีทั้งคำพูดถูกต้องและการกระทำที่รับผิดชอบ'))
add('slide-03-reasonable-care','Due care means reasonable protection in context.','Due Care คือการปกป้องที่สมเหตุสมผลตามบริบท',('Choose and carry out prudent safeguards for the actual risk.','เลือกและใช้มาตรการอย่างรอบคอบให้เหมาะกับความเสี่ยงจริง'),rows(
 [('Context','บริบท'),('An exposed service has a confirmed weakness.','บริการที่เปิดรับภายนอกมีจุดอ่อนที่ยืนยันแล้ว'),('Consider impact, duties and operating needs.','พิจารณาผลกระทบ หน้าที่ และความต้องการใช้งาน')],
 [('Protective action','ลงมือปกป้อง'),('Apply an approved patch or a justified interim safeguard.','ติดตั้ง Patch ที่อนุมัติหรือมาตรการชั่วคราวที่มีเหตุผล'),('Use change authority and a safe plan.','มีอำนาจเปลี่ยนแปลงและแผนที่ปลอดภัย')],
 [('Accountable record','บันทึกความรับผิดชอบ'),('Record the action, owner and remaining exposure.','บันทึกการกระทำ ผู้รับผิดชอบ และความเสี่ยงที่เหลือ'),('Reasonable does not mean risk-free.','สมเหตุสมผลไม่ได้แปลว่าไร้ความเสี่ยง')]),
 ('A §47 describes due care as reasonable steps to protect assets and reduce risk; B §7.3 gives reasonable precautions and suitable controls. ISACA’s glossary similarly grounds care in what a comparably competent person would do under similar conditions. An original exposed-service example requires considering the known weakness, likely harm, applicable duties and operational impact, then carrying out an approved protective response. Patching may be appropriate; if a safe patch is not immediately possible, an authorized interim restriction and an accountable follow-up may be needed. Doing nothing silently is not the same as a justified decision. Due care is not buying every possible control, applying a dangerous change without authority, or guaranteeing that no incident can occur. A checklist or the label “due care” alone does not establish legal immunity; professional reasoning and operating evidence matter.','A §47 อธิบาย Due Care ว่าดำเนินการสมเหตุสมผลเพื่อปกป้องทรัพย์สินและลด Risk ส่วน B §7.3 เน้นความระมัดระวังและ Controls ที่เหมาะสม ISACA อธิบายโดยเทียบกับผู้มีความสามารถใกล้เคียงในสถานการณ์คล้ายกัน ตัวอย่างบริการที่เปิดภายนอกต้องพิจารณาจุดอ่อนที่รู้ ผลเสียที่อาจเกิด หน้าที่เกี่ยวข้อง และผลต่อการใช้งาน แล้วลงมือปกป้องตามอำนาจที่อนุมัติ การติดตั้ง Patch อาจเหมาะสม ถ้าทำอย่างปลอดภัยไม่ได้ทันที อาจต้องจำกัดการเข้าถึงชั่วคราวตามอำนาจพร้อมผู้รับผิดชอบติดตาม การปล่อยไว้เงียบ ๆ ไม่เท่ากับตัดสินใจอย่างมีเหตุผล Due Care ไม่ใช่ซื้อทุก Control เปลี่ยนระบบอันตรายโดยไม่มีอำนาจ หรือรับประกันว่าจะไม่เกิดเหตุ Checklist หรือชื่อ Due Care อย่างเดียวไม่พิสูจน์ความพ้นผิดทางกฎหมาย ต้องมีเหตุผลและหลักฐานการทำงาน'),('Protect reasonably, act within authority, and explain the decision.','ปกป้องอย่างสมเหตุสมผล ทำตามอำนาจ และอธิบายการตัดสินใจ'))
add('slide-04-investigate-and-review','Due diligence builds and refreshes the evidence.','Due Diligence สร้างและทบทวนหลักฐานให้ทันสถานการณ์',('Investigate before a decision; review effectiveness after action and change.','ตรวจสอบก่อนตัดสินใจ และทบทวนผลหลังลงมือหรือเมื่อบริบทเปลี่ยน'),rows(
 [('Investigate','ตรวจสอบข้อมูล'),('Confirm the affected service and the finding.','ยืนยันบริการที่ได้รับผลและข้อค้นพบ'),('Do not rely on a tool’s label alone.','ไม่เชื่อเพียงป้ายผลจากเครื่องมือ')],
 [('Evaluate','ประเมิน'),('Check whether the chosen safeguard meets the need.','ตรวจว่ามาตรการตอบความต้องการหรือไม่'),('An installation record is not an effectiveness test.','บันทึกว่าติดตั้งไม่ใช่ผลทดสอบประสิทธิผล')],
 [('Keep reviewing','ทบทวนต่อเนื่อง'),('Reassess when risk, technology or obligations change.','ประเมินใหม่เมื่อ Risk เทคโนโลยี หรือข้อกำหนดเปลี่ยน'),('Evidence can become outdated.','หลักฐานอาจล้าสมัยได้')]),
 ('A §48 describes investigation, evaluation and awareness of changing risk. B §7.3 emphasizes careful assessment and monitoring. ISACA describes prudent, responsible investigation, review or analysis. Diligence therefore includes work before and after a protective action, not only a final inspection. In the service example, verify the scan’s scope and findings before deciding what change is appropriate; after the change, inspect operating evidence and residual exposure. Later software, service or threat changes can invalidate old conclusions. Use authorized methods and the appropriate skill: collecting unlimited sensitive data is not automatically better investigation. State evidence limitations and route unresolved questions to a responsible person. Care and diligence reinforce one another and may overlap in actual work; the course distinction helps identify the emphasis, not assign every task to a universal exclusive bucket.','A §48 กล่าวถึงการตรวจสอบ ประเมิน และตระหนักถึง Risk ที่เปลี่ยน ส่วน B §7.3 เน้นประเมินและติดตามอย่างรอบคอบ ISACA อธิบายการตรวจสอบ ทบทวน หรือวิเคราะห์อย่างมีความรับผิดชอบ ดังนั้น Diligence มีทั้งก่อนและหลังการปกป้อง ไม่ใช่ตรวจครั้งสุดท้ายเท่านั้น ในตัวอย่างบริการต้องยืนยันขอบเขตและผล Scan ก่อนตัดสินใจเปลี่ยน หลังเปลี่ยนต้องตรวจหลักฐานการทำงานและความเสี่ยงที่เหลือ ต่อมาเมื่อซอฟต์แวร์ บริการ หรือภัยเปลี่ยน ข้อสรุปเก่าอาจใช้ไม่ได้ ต้องใช้วิธีที่มีอำนาจและทักษะเหมาะสม เก็บข้อมูลอ่อนไหวไม่จำกัดไม่ได้แปลว่าตรวจสอบดีกว่า ระบุข้อจำกัดหลักฐานและส่งประเด็นค้างให้ผู้รับผิดชอบ Care กับ Diligence สนับสนุนและทับซ้อนกันได้ การแยกในคอร์สช่วยเห็นจุดเน้น ไม่ใช่บังคับทุกงานอยู่ได้ช่องเดียว'),('Good inquiry informs action—and checks whether it still works.','การตรวจสอบที่ดีช่วยเลือกการกระทำและตรวจว่ายังได้ผล'))
add('slide-05-scan-patch-verify','Investigate → protect → verify → keep reviewing.','ตรวจสอบ → ปกป้อง → ยืนยันผล → ทบทวนต่อ',('Follow one authorized service change through care and diligence.','ติดตามการเปลี่ยนบริการที่มีอำนาจผ่านทั้ง Care และ Diligence'),rows(
 [('1 · Assess','1 · ประเมิน'),('Validate the scan finding and affected scope.','ตรวจยืนยันผล Scan และขอบเขตที่ได้รับผล'),('Diligence: investigate the risk.','Diligence: ตรวจสอบความเสี่ยง')],
 [('2 · Act','2 · ลงมือ'),('Apply the approved patch with a safe change plan.','ติดตั้ง Patch ที่อนุมัติตามแผนปลอดภัย'),('Care: carry out reasonable protection.','Care: ลงมือปกป้องอย่างสมเหตุสมผล')],
 [('3 · Verify','3 · ยืนยันผล'),('Rescan, check service behavior and review residual risk.','Scan ซ้ำ ตรวจบริการ และทบทวน Risk ที่เหลือ'),('Diligence: test the result and continue review.','Diligence: ตรวจผลและทบทวนต่อ')]),
 ('A §49 supplies the scan→patch→rescan teaching example, supported by B §7.3. A’s DO/CHECK distinction is a memory aid, not an exhaustive definition or a universal legal test. Assessment can occur before action, and prudent implementation itself includes checks. In this original service-change scenario, an authorized scan identifies a weakness; the team verifies its applicability, chooses an appropriate response and obtains change approval. It applies the patch safely, then rescans and tests that the service still behaves correctly. A patch completion ticket alone cannot prove the vulnerability is resolved or the service is safe. Document exceptions, remaining risk, an owner and further review. Care without informed evaluation may act on the wrong problem; investigation without reasonable follow-through leaves known exposure. The cycle continues when conditions change.','A §49 ยกตัวอย่าง Scan→Patch→Scan ซ้ำ และ B §7.3 สนับสนุนคำอธิบาย ชุด DO/CHECK ของ A เป็นคำช่วยจำ ไม่ใช่นิยามทั้งหมดหรือเกณฑ์กฎหมายสากล การประเมินเกิดก่อนลงมือได้ และการเปลี่ยนอย่างรอบคอบก็มีการตรวจอยู่ด้วย ในตัวอย่างการเปลี่ยนบริการนี้ Scan ตามอำนาจพบจุดอ่อน ทีมตรวจว่าเกี่ยวข้องจริง เลือกวิธีตอบสนอง และขออนุมัติเปลี่ยนแปลง จากนั้นติดตั้ง Patch อย่างปลอดภัยแล้ว Scan ซ้ำพร้อมทดสอบพฤติกรรมบริการ Ticket ว่าติดตั้งเสร็จอย่างเดียวไม่พิสูจน์ว่าจุดอ่อนหายหรือบริการปลอดภัย ต้องบันทึกข้อยกเว้น Risk ที่เหลือ ผู้รับผิดชอบ และการทบทวนต่อ Care ที่ไม่ประเมินข้อมูลอาจแก้ผิดเรื่อง ส่วนการตรวจโดยไม่ทำสิ่งที่เหมาะสมต่อปล่อยให้ยังมีความเสี่ยง วงจรดำเนินต่อเมื่อเงื่อนไขเปลี่ยน'),('“Done” needs evidence of the result, not just the activity.','คำว่าเสร็จต้องมีหลักฐานผล ไม่ใช่เพียงบันทึกกิจกรรม'))
add('slide-06-four-canons','Four canons frame professional judgment.','หลักจริยธรรมสี่ข้อช่วยกำกับการตัดสินใจ',('Learning paraphrases: consult the official Code for its exact wording.','สรุปความเพื่อเรียนรู้ อ่านถ้อยคำต้นฉบับจาก Code ทางการ'),rows(
 [('I · Society','I · สังคม'),('Protect public welfare, shared interests, trust and infrastructure.','ปกป้องสวัสดิภาพส่วนรวม ความไว้วางใจ และโครงสร้างพื้นฐาน'),('Consider people beyond your employer.','คิดถึงผู้ได้รับผลนอกองค์กรด้วย')],
 [('II · Conduct','II · ความประพฤติ'),('Act with integrity, fairness, responsibility and legality.','ประพฤติซื่อตรง เป็นธรรม รับผิดชอบ และถูกกฎหมาย'),('Honest reporting matters under pressure.','ต้องรายงานซื่อตรงแม้มีแรงกดดัน')],
 [('III · Principals','III · ผู้รับบริการ'),('Give principals competent, diligent service.','บริการผู้ว่าจ้างหรือลูกค้าอย่างรอบคอบและมีความสามารถ'),('Professional service includes knowing your limits.','รู้ข้อจำกัดทักษะเป็นส่วนหนึ่งของวิชาชีพ')],
 [('IV · Profession','IV · วิชาชีพ'),('Strengthen and safeguard the profession.','ส่งเสริมและปกป้องวิชาชีพ'),('Develop skills and support ethical practice.','พัฒนาทักษะและสนับสนุนการปฏิบัติที่มีจริยธรรม')]),
 ('A §§50–51 and B §8 introduce the four ISC2 canons. These teaching paraphrases preserve their substance: protect society, the common good, public trust/confidence and infrastructure; act honorably with honesty, justice, responsibility and legality; serve principals diligently and competently; and advance/protect the profession. A principal here includes an employer or client to whom a professional service duty is owed, not automatically any person who gives an instruction. The official Code identifies four mandatory canons and explicitly retains the need for professional judgment. Its expectations apply to ISC2 members; newcomers can use them to understand professional standards without claiming certification. The notes’ S→A→P→P cue helps recall the listed order but is not a mechanical answer to every conflict. Consider the facts, authority, affected people and applicable duties together; the linked official page supplies exact wording and the separate complaint procedure.','A §§50–51 และ B §8 แนะนำหลัก ISC2 สี่ข้อ สรุปความนี้รักษาสาระคือปกป้องสังคม ประโยชน์ส่วนรวม ความไว้วางใจและความเชื่อมั่นสาธารณะ รวมโครงสร้างพื้นฐาน ประพฤติอย่างมีเกียรติ ซื่อสัตย์ เป็นธรรม รับผิดชอบและถูกกฎหมาย บริการ Principals อย่างรอบคอบและมีความสามารถ และส่งเสริมปกป้องวิชาชีพ Principal ในที่นี้รวมผู้ว่าจ้างหรือลูกค้าที่เรามีหน้าที่ให้บริการ ไม่ใช่ทุกคนที่ออกคำสั่ง Code ทางการระบุสี่ข้อที่ต้องปฏิบัติและย้ำว่าต้องใช้วิจารณญาณวิชาชีพ ข้อกำหนดนี้ใช้กับสมาชิก ISC2 ผู้เริ่มเรียนใช้เข้าใจมาตรฐานได้โดยไม่อ้างว่าตนได้รับการรับรอง คำช่วยจำ S→A→P→P ช่วยจำลำดับที่แสดง ไม่ใช่สูตรตอบทุกความขัดแย้ง ต้องดูข้อเท็จจริง อำนาจ ผู้ได้รับผล และหน้าที่ร่วมกัน ลิงก์ทางการมีถ้อยคำเต็มและกระบวนการร้องเรียนแยกต่างหาก'),('Know the obligations, then apply them to the actual facts.','รู้หน้าที่ แล้วใช้กับข้อเท็จจริงของสถานการณ์'))
add('slide-07-public-trust-and-honesty','Protect people without distorting the finding.','ปกป้องผู้คนโดยไม่บิดเบือนข้อค้นพบ',('A serious weakness needs truthful information and a safe response.','จุดอ่อนร้ายแรงต้องได้ข้อมูลตรงจริงและการตอบสนองปลอดภัย'),rows(
 [('Affected people','ผู้ได้รับผล'),('A service weakness could expose users to harm.','จุดอ่อนบริการอาจทำให้ผู้ใช้ได้รับอันตราย'),('Public welfare is wider than a project deadline.','สวัสดิภาพส่วนรวมกว้างกว่าเส้นตายโครงการ')],
 [('Accurate record','บันทึกตรงจริง'),('Record verified facts, scope and uncertainty.','บันทึกข้อเท็จจริงที่ตรวจแล้ว ขอบเขต และความไม่แน่นอน'),('Do not hide or exaggerate the evidence.','ไม่ปกปิดหรือกล่าวเกินหลักฐาน')],
 [('Safe escalation','ส่งต่ออย่างปลอดภัย'),('Use the appropriate responsible and authorized channels.','ใช้ช่องทางที่เหมาะสมไปยังผู้รับผิดชอบตามอำนาจ'),('Urgency does not justify an indiscriminate data dump.','ความเร่งด่วนไม่ใช่เหตุให้ปล่อยข้อมูลไม่จำกัด')]),
 ('A §46 and the first two canons in A §50/B §8 connect protection of others with honest, responsible conduct. Consider an original assessment that finds a serious weakness before a service handover. Pressure to meet a deadline does not justify removing a verified material finding from the report. Explain evidence, likely consequences and uncertainty accurately; avoid unsupported claims of exploitation. Protect sensitive details and raise the issue through the appropriate responsible channels, seeking qualified advice when duties or authority conflict. A public-interest concern does not automatically authorize releasing personal data or exploit details to everyone. Conversely, confidentiality is not a reason to falsify a report or avoid all escalation. If immediate safety is at stake, use applicable urgent response routes and competent support. This is professional reasoning, not a universal disclosure deadline or legal determination.','A §46 และสองข้อแรกใน A §50/B §8 เชื่อมการปกป้องผู้อื่นกับความซื่อสัตย์และความรับผิดชอบ ลองพิจารณาตัวอย่างผลประเมินพบจุดอ่อนร้ายแรงก่อนส่งมอบบริการ แรงกดดันเรื่องเส้นตายไม่ใช่เหตุให้ลบข้อค้นพบสำคัญที่ตรวจแล้วออกจากรายงาน ต้องบอกหลักฐาน ผลที่อาจเกิด และความไม่แน่นอนตรงจริง ไม่อ้างว่ามีการโจมตีแล้วโดยไร้หลักฐาน ปกป้องรายละเอียดอ่อนไหวและส่งประเด็นผ่านช่องทางที่เหมาะสมไปยังผู้รับผิดชอบ ขอคำแนะนำที่มีคุณสมบัติเมื่อหน้าที่หรืออำนาจขัดกัน การห่วงส่วนรวมไม่ได้อนุญาตอัตโนมัติให้ปล่อยข้อมูลส่วนตัวหรือรายละเอียดโจมตีให้ทุกคน ในทางกลับกัน ความลับก็ไม่ใช่เหตุให้ปลอมรายงานหรือไม่ส่งต่อเลย ถ้าความปลอดภัยเร่งด่วนให้ใช้ช่องทางฉุกเฉินที่เกี่ยวข้องพร้อมผู้มีความสามารถ นี่เป็นการใช้เหตุผลวิชาชีพ ไม่ใช่เส้นตายเปิดเผยหรือข้อวินิจฉัยกฎหมายสากล'),('Be truthful, limit unnecessary exposure, and seek accountable action.','รายงานตรงจริง จำกัดการเปิดเผยเกินจำเป็น และหาการดำเนินการที่รับผิดชอบ'))
add('slide-08-competent-service','Serve principals competently—and strengthen the profession.','บริการอย่างมีความสามารถและส่งเสริมวิชาชีพ',('Responsible service includes clear limits, qualified help and continued learning.','บริการที่รับผิดชอบต้องบอกขีดจำกัด ขอผู้มีความสามารถช่วย และเรียนรู้ต่อ'),rows(
 [('Know your limits','รู้ขีดจำกัด'),('Disclose that a requested specialist review exceeds your skill.','แจ้งว่างานตรวจเฉพาะทางเกินทักษะตน'),('Do not sign a claim you cannot support.','ไม่ลงชื่อรับรองสิ่งที่ยืนยันไม่ได้')],
 [('Arrange competent service','จัดให้บริการเหมาะสม'),('Seek qualified support and agree an authorized scope.','ขอผู้มีความสามารถช่วยและตกลงขอบเขตตามอำนาจ'),('Principals need honest advice, not blind agreement.','ผู้ว่าจ้างต้องได้คำแนะนำตรงจริง ไม่ใช่เห็นด้วยทุกเรื่อง')],
 [('Support the profession','สนับสนุนวิชาชีพ'),('Learn, mentor responsibly and share only permitted material.','เรียนรู้ ให้คำแนะนำรับผิดชอบ และแบ่งปันเฉพาะสิ่งที่อนุญาต'),('Protect client confidentiality while helping others.','ช่วยผู้อื่นโดยยังรักษาความลับลูกค้า')]),
 ('The third canon in A §50/B §8 concerns diligent and competent service to principals, including employers and clients. The fourth concerns advancing and protecting the profession. In this original example, a junior analyst is asked to sign off a specialist review outside their competence. Honest service means explaining the limitation, seeking qualified help and arranging appropriate supervision or scope rather than inventing expertise or abandoning the duty without handover. Loyalty does not require obeying an instruction to mislead others or exceed authorization. Continuing professional development, responsible mentoring and accurate sharing can support the profession, but client records, credentials and confidential material must remain protected. A wish to teach does not grant disclosure rights. Apply the official canons with the facts and relevant responsibilities rather than assuming that employer benefit always settles an ethical conflict.','ข้อสามใน A §50/B §8 เน้นบริการ Principals เช่นผู้ว่าจ้างและลูกค้าอย่างรอบคอบและมีความสามารถ ข้อสี่เน้นส่งเสริมและปกป้องวิชาชีพ ตัวอย่างนี้นักวิเคราะห์ใหม่ถูกขอให้รับรองงานเฉพาะทางที่เกินความสามารถ การบริการซื่อตรงคือแจ้งข้อจำกัด ขอผู้มีความสามารถช่วย และจัดการกำกับหรือขอบเขตให้เหมาะสม ไม่แต่งความเชี่ยวชาญหรือทิ้งหน้าที่โดยไม่ส่งมอบ ความภักดีไม่ได้บังคับให้ทำตามคำสั่งที่หลอกผู้อื่นหรือเกินสิทธิ์ การพัฒนาต่อเนื่อง ให้คำแนะนำรับผิดชอบ และแบ่งปันข้อมูลถูกต้องช่วยวิชาชีพได้ แต่ต้องปกป้องข้อมูลลูกค้า Credential และสิ่งลับ เจตนาจะสอนไม่ได้ให้สิทธิ์เปิดเผย ต้องใช้หลักทางการร่วมกับข้อเท็จจริงและความรับผิดชอบ ไม่ถือว่าประโยชน์นายจ้างตัดสินความขัดแย้งได้ทุกครั้ง'),('Honest limits and qualified help are part of professional service.','บอกข้อจำกัดตรงจริงและขอผู้มีความสามารถช่วยเป็นส่วนหนึ่งของบริการวิชาชีพ'))
add('slide-09-reporting-decision','A deadline does not justify hiding a serious finding.','เส้นตายไม่ใช่เหตุให้ปกปิดข้อค้นพบร้ายแรง',('You verified a serious weakness. A supervisor asks you to omit it. Inspect each response.','คุณตรวจยืนยันจุดอ่อนร้ายแรง หัวหน้าขอให้ตัดออก ลองพิจารณาการตอบแต่ละแบบ'),rows(
 [('Concealment','การปกปิด'),('Hiding the finding leaves responsible people uninformed.','ปิดข้อค้นพบทำให้ผู้รับผิดชอบขาดข้อมูล'),('A deadline does not justify a misleading report.','เส้นตายไม่ใช่เหตุให้รายงานหลอกลวง')],
 [('Uncontrolled disclosure','การเผยแพร่ไร้ขอบเขต'),('Publishing client records creates additional harm.','เผยแพร่ข้อมูลลูกค้าสร้างผลเสียเพิ่ม'),('Public welfare does not remove confidentiality duties.','ประโยชน์ส่วนรวมไม่ลบหน้าที่รักษาความลับ')],
 [('Accurate, protected escalation','รายงานตรงจริงและส่งต่อปลอดภัย'),('Retain verified facts and use appropriate responsible channels.','เก็บข้อเท็จจริงที่ตรวจแล้วและใช้ช่องทางเหมาะสมไปยังผู้รับผิดชอบ'),('Protect details; seek qualified advice if duties conflict.','ปกป้องรายละเอียด ขอคำแนะนำที่มีคุณสมบัติเมื่อหน้าที่ขัดกัน')]),
 ('This original practice scenario applies A §46 and A §50/B §8. It is not an actual exam question. The stated facts are that the analyst is authorized to assess the service, has verified a serious weakness and is being asked to omit it because of a deadline. Concealment undermines honest competent service and informed protection of affected people. Publishing client records indiscriminately is also inappropriate: it creates exposure without establishing authority or a lawful need to disclose those records. Accurate, protected escalation is the supported response in these facts: preserve the finding and uncertainty, limit sensitive detail to those who need it, and use the appropriate responsible channels. The exact recipient and urgent duties depend on context; competent advice may be needed. Feedback explains the consequences of all three actions without claiming a universal channel hierarchy, disclosure rule or guaranteed resolution.','แบบฝึกแต่งขึ้นนี้ใช้ A §46 และ A §50/B §8 ไม่ใช่ข้อสอบจริง ข้อเท็จจริงคือนักวิเคราะห์มีอำนาจประเมิน ตรวจยืนยันจุดอ่อนร้ายแรง และถูกขอให้ตัดออกเพราะเส้นตาย การปกปิดบั่นทอนบริการซื่อตรงที่มีความสามารถและทำให้ตัดสินใจปกป้องผู้ได้รับผลไม่ได้ ส่วนการเผยแพร่ข้อมูลลูกค้าไม่จำกัดก็ไม่เหมาะ เพราะสร้างการเปิดเผยโดยยังไม่มีอำนาจหรือความจำเป็นตามกฎหมาย การรายงานตรงจริงและส่งต่อปลอดภัยจึงเป็นคำตอบที่ข้อเท็จจริงนี้รองรับ เก็บข้อค้นพบและความไม่แน่นอน จำกัดรายละเอียดให้ผู้จำเป็น และใช้ช่องทางเหมาะสมไปยังผู้รับผิดชอบ ผู้รับที่แน่นอนและหน้าที่เร่งด่วนขึ้นกับบริบท อาจต้องมีคำแนะนำจากผู้มีความสามารถ Feedback อธิบายผลทั้งสามทางโดยไม่อ้างว่ามีลำดับช่องทาง กฎเปิดเผย หรือผลสำเร็จที่รับประกันทุกกรณี'),('Protect the truth and the information—not the deadline at any cost.','รักษาความจริงและข้อมูล ไม่ยึดเส้นตายโดยยอมทำทุกอย่าง'))
add('slide-10-defensible-decisions','Make the decision explainable—and review the result.','อธิบายการตัดสินใจได้ และตรวจผลที่เกิดขึ้น',('Connect authority, evidence, professional duties and follow-through.','เชื่อมอำนาจ หลักฐาน หน้าที่วิชาชีพ และการติดตามผล'),rows(
 [('Purpose and authority','วัตถุประสงค์และอำนาจ'),('Who may act, for what task, and who may be affected?','ใครมีอำนาจทำงานอะไร และใครอาจได้รับผล?'),('Include people beyond the immediate requester.','มองผู้ได้รับผลนอกเหนือผู้สั่งงาน')],
 [('Evidence and obligations','หลักฐานและหน้าที่'),('What is verified, uncertain, required and within your competence?','อะไรตรวจแล้ว อะไรไม่แน่ ต้องทำอะไร และทักษะพอหรือไม่?'),('An AI-generated draft is not verified evidence.','ร่างที่ AI สร้างไม่ใช่หลักฐานที่ตรวจแล้ว')],
 [('Action and review','ลงมือและทบทวน'),('Record a proportionate response, owner and review point.','บันทึกการตอบสนองเหมาะสม ผู้รับผิดชอบ และจุดทบทวน'),('Check the outcome and update when facts change.','ตรวจผลและปรับเมื่อข้อเท็จจริงเปลี่ยน')]),
 ('A §§46–51 and B §§7.3,8 connect conduct, care, inquiry and ethical obligations. This original decision record is a reasoning aid, not an official mandatory sequence. Confirm the authorized purpose and affected people; distinguish evidence from assumptions; consider applicable duties, confidentiality, competence and potential harm; choose a reasonable response; record the owner and follow-up. In a supplemental AI example grounded in the official outline’s Domain 1 AI context, an analyst receives an AI-generated security report. Professional responsibility remains with the people approving and acting on it: check factual support, sensitive-data handling, misleading or unfair claims and the limits of the tool before authorized use. Do not upload protected records to an unapproved service just to validate the draft. Seeking qualified review when uncertain is consistent with competent service. Evaluate the eventual outcome and revisit the decision when conditions change.','A §§46–51 และ B §§7.3,8 เชื่อมความประพฤติ ความระมัดระวัง การตรวจสอบ และหน้าที่จริยธรรม บันทึกการตัดสินใจที่แต่งขึ้นนี้เป็นเครื่องช่วยคิด ไม่ใช่ลำดับบังคับทางการ ยืนยันวัตถุประสงค์ตามอำนาจและผู้ได้รับผล แยกหลักฐานจากสมมติฐาน พิจารณาหน้าที่ ความลับ ความสามารถและผลเสีย เลือกการตอบสนองสมเหตุสมผล บันทึกผู้รับผิดชอบและการติดตาม ตัวอย่าง AI เสริมตามบริบท Domain 1 ใน Outline ทางการคือนักวิเคราะห์ได้รายงานความปลอดภัยที่ AI สร้าง ผู้อนุมัติและนำไปใช้ยังรับผิดชอบ ต้องตรวจข้อมูลรองรับ การจัดการข้อมูลอ่อนไหว ข้ออ้างที่หลอกลวงหรือไม่เป็นธรรม และข้อจำกัดเครื่องมือก่อนใช้ตามอำนาจ ไม่ส่งข้อมูลที่ต้องปกป้องไปบริการที่ไม่อนุมัติเพียงเพื่อเช็กร่าง ขอผู้มีความสามารถตรวจเมื่อไม่แน่ใจสอดคล้องกับบริการวิชาชีพ ตรวจผลจริงและทบทวนเมื่อเงื่อนไขเปลี่ยน'),('Reason carefully, act responsibly, verify and keep learning.','คิดรอบคอบ ทำอย่างรับผิดชอบ ตรวจผล และเรียนรู้ต่อ'))
